    def checks_injection(self):
        sqli_hits, xss_hits = [], []
        for method, path, _extra, _idx in self._fuzz_targets():
            if method == "GET":
                r = self._probe_get(path, single=True)
            else:
                continue  # POST body fuzzing limited to JSON schemas below
            if r is None:
                continue
            sql_hit = self.SQL_ERR_RE.search(r.text)
            if sql_hit:
                sqli_hits.append((method, path, r))
            xss = self._reflected_xss(path, r)
            if xss:
                xss_hits.append((method, path, xss))
        if sqli_hits:
            m, p, r = sqli_hits[0]
            self.add("SQL injection (error-based)", f"{m} {self.base(p)}",
                     "A03", "CRITICAL", r.text[:220],
                     "Use parameterized queries / an ORM; escape identifiers.")
        else:
            self.add("No obvious error-based SQLi on probed endpoints", self.base("/"), "A03", "PASS")
        if xss_hits:
            m, p, ev = xss_hits[0]
            self.add("Reflected XSS", f"{m} {self.base(p)}", "A03", "HIGH",
                     f"Reflected marker: {ev}", "Encode output context and add CSP.")
        else:
            self.add("No reflected XSS detected on probed endpoints", self.base("/"), "A03", "PASS")

    def _probe_get(self, path: str, single: bool = False) -> httpx.Response | None:
        payload = "' OR '1'='1"
        for sep in ("?", "&f="):
            url = path + sep + urllib.parse.quote(payload)
        r = self._fuzz_request("GET", path, payload)
        return r

    def _fuzz_request(self, method: str, path: str, payload: str) -> httpx.Response | None:
        url = path + "?" + urllib.parse.urlencode({"q": payload})
        return self._safe_req(method, url, timeout=8)

    def _safe_req(self, method: str, url: str, **kw) -> httpx.Response | None:
        try:
            return self.client.request(method, url, **kw)
        except httpx.HTTPError:
            return None

    def _reflected_xss(self, path: str, base: httpx.Response | None) -> str | None:
        probe = path + "?" + urllib.parse.urlencode({"q": f"{self.XSS_MARKER}<script>"})
        r = self._safe_req("GET", probe)
        if r and self.XSS_MARKER in r.text:
            idx = r.text.find(self.XSS_MARKER)
            return r.text[max(0, idx - 40): idx + 60]
        return None

    def checks_traversal(self):
        payload = "../../../../../../../../etc/passwd"
        for method, path, _e, _i in self._fuzz_targets()[:60]:
            if method != "GET":
                continue
            url = path + "?" + urllib.parse.urlencode({"file": payload})
            r = self._safe_req("GET", url)
            if r and ("root:" in r.text or self.TRAV_MARKER in r.text):
                self.add("Path traversal (reads ../etc/passwd)", f"GET {self.base(url)}",
                         "A03", "CRITICAL", r.text[:220],
                         "Never trust filenames; sanitize and canonicalize paths.")
                return
        self.add("No path traversal detected on sampled endpoints", self.base("/"), "A03", "PASS")

    def checks_command_injection(self):
        payload = "1; id; echo X"
        for method, path, _e, _i in self._fuzz_targets()[:40]:
            if method != "GET":
                continue
            url = path + "?" + urllib.parse.urlencode({"cmd": payload})
            r = self._safe_req("GET", url)
            if r and ("uid=" in r.text or "X\n" in r.text):
                self.add("Command injection", f"GET {self.base(url)}", "A03", "CRITICAL",
                         r.text[:220], "Do not pass user input to a shell.")

