class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body, ctype="text/html"):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        if code == 200:
            self.send_header("Set-Cookie", "session=abc123; Path=/")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Credentials", "true")
        self.end_headers()
        if isinstance(body, str):
            body = body.encode()
        self.wfile.write(body)

    def do_GET(self):
        from urllib.parse import urlsplit, parse_qs
        path = urlsplit(self.path).path
        qs = parse_qs(urlsplit(self.path).query)
        if path == "/openapi.json":
            return self._send(200, json.dumps({
                "openapi": "3.0.0",
                "info": {"title": "evil", "version": "1.0"},
                "paths": {
                    "/search": {"get": {"parameters": [
                        {"name": "q", "in": "query", "required": True, "schema": {"type": "string"}}]}},
                    "/fetch": {"get": {"parameters": [
                        {"name": "url", "in": "query", "schema": {"type": "string"}}]}},
                    "/read": {"get": {"parameters": [
                        {"name": "file", "in": "query", "schema": {"type": "string"}}]}},
                    "/run": {"get": {"parameters": [
                        {"name": "cmd", "in": "query", "schema": {"type": "string"}}]}},
                    "/admin": {"get": {}},
                },
            }), "application/json")
        if path == "/":
            return self._send(200, '<html><a href="/search">search</a>'
                                    '<a href="/admin">admin</a></html>')
        if path == "/search":
            q = qs.get("q", [""])[0]
            try:
                conn.execute("SELECT * FROM t WHERE name='" + q + "'")
            except sqlite3.Error as e:
                return self._send(500, "<pre>ERROR: " + repr(e) + "</pre>")
            return self._send(200, "no results for " + q + "<script>" + q + "</script>")
        if path == "/fetch":
            url = qs.get("url", [""])[0]
            return self._send(200, "fetching " + url)
        if path == "/read":
            fn = qs.get("file", [""])[0]
            try:
                return self._send(200, open(fn).read())
            except OSError:
                return self._send(404, "nope")
        if path == "/run":
            cmd = qs.get("cmd", [""])[0]
            try:
                return self._send(200, subprocess.check_output(cmd, shell=True)[:500])
            except Exception:
                return self._send(500, "err")
        if path == "/admin":
            return self._send(200, "ADMIN PANEL - full access")
        if path == "/.env":
            return self._send(200, "SECRET_KEY=supersecret123\nDATABASE_URL=postgres://x:y@db")
        if path == "/.git/config":
            return self._send(200, "[remote \"origin\"]\n\turl = https://example.com/repo.git")
        return self._send(404, "<html>not found</html>")

    def do_POST(self):
        return self._send(415, "unsupported")


