import json
import sqlite3
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlsplit, parse_qs

conn = sqlite3.connect(":memory:", check_same_thread=False)
conn.executescript("""
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT, secret_hash TEXT);
CREATE TABLE notes (id INTEGER PRIMARY KEY, user_id INTEGER, body TEXT);
INSERT INTO users VALUES (1, 'admin', 'admin@evil.local', 'sha256:abc123def');
INSERT INTO users VALUES (2, 'bob', 'bob@evil.local', 'sha256:deadbeef');
INSERT INTO notes VALUES (1, 1, 'remember to ship');
INSERT INTO notes VALUES (2, 1, 'meeting friday');
""")
conn.commit()


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body, ctype="text/html"):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.end_headers()
        if isinstance(body, str):
            body = body.encode("utf8", "replace")
        self.wfile.write(body)

    def do_GET(self):
        path = urlsplit(self.path).path
        qs = parse_qs(urlsplit(self.path).query)
        if path == "/openapi.json":
            return self._send(200, json.dumps({
                "openapi": "3.0.0",
                "info": {"title": "evil-target", "version": "1.0"},
                "paths": {"/search": {"get": {"parameters": [
                    {"name": "q", "in": "query", "required": True,
                     "schema": {"type": "string"}}]}}},
            }), "application/json")
        if path == "/search":
            q = qs.get("q", [""])[0]
            try:
                cur = conn.execute("SELECT id, name, email FROM users WHERE name='" + q + "'")
                rows = cur.fetchall()
            except Exception:
                return self._send(500, "<pre>ERROR</pre>")
            if rows:
                body = "<table>" + "".join(
                    "<tr>" + "".join(str(c) for c in r) + "</tr>" for r in rows) + "</table>"
                return self._send(200, body)
            return self._send(200, "no results for " + q)
        return self._send(404, "not found")

    def do_POST(self):
        return self._send(415, "unsupported")


if __name__ == "__main__":
    HTTPServer(("127.0.0.1", 8899), H).serve_forever()

