    segs = [s for s in tpl.strip("/").split("/") if s and "/" in ("/" + s) ]
    static = [s for s in tpl.strip("/").split("/") if "{" not in s]
    return "_".join(static[-2:]) or "rows"


def _harvest_ids(obj: dict, known: dict[str, set[str]]):
    for k, v in obj.items():
        if k == "id" or str(k).endswith("_id"):
            if isinstance(v, (int, str)):
                known.setdefault(k, set()).add(str(v))
        elif isinstance(v, list):
            for sub in v:
                if isinstance(sub, dict):
                    _harvest_ids(sub, known)


def _iter_rows(data) -> list:
    if isinstance(data, list):
        return [d for d in data if isinstance(d, dict)]
    if isinstance(data, dict):
        for key in LIST_KEYS:
            val = data.get(key)
            if isinstance(val, list):
                return [d for d in val if isinstance(d, dict)]
        return [data] if data else []
    return []


def crawl(target, args) -> dict[str, list[dict]]:
    """Return {sheet_label: [flattened rows]} copied through the API."""
    all_routes = [e.path for e in target.endpoints if e.method == "GET"]
    roots = sorted({p for p in all_routes if "{" not in p})
    templates = sorted({p for p in all_routes if "{" in p})

    known: dict[str, set[str]] = {}
    rows: dict[str, dict[str, dict]] = {}   # label -> (source|id -> row)
    visited: set[str] = set()
    queue: list[str] = roots[:]
    max_req = getattr(args, "max_requests", 2000)
    max_ids = getattr(args, "max_ids", 500)
    dedupe_since: dict[str, int] = {}

    def record(label: str, source: str, obj: dict, ids: tuple):
        key = (source,) + ids if ids else (source, json.dumps(obj, sort_keys=True))
        rows.setdefault(label, {})[key] = _flatten(obj, source)

    def note_change():
        return sum(len(s) for s in known.values())

    last_count = 0
    while queue and len(visited) < max_req:
        url = queue.pop(0)
        if url in visited:
            continue
        visited.add(url)
        status, data, err = net.get_json(target, url)
        if status is None or err or data is None:
            continue
        if isinstance(data, dict) and any("list" in k for k in LIST_KEYS) is False:
            pass
