            ids = tuple(str(obj[k]) for k in ("id",) if k in obj)
            record(label, url, obj, ids)
            _harvest_ids(obj, known)

        # expand templates whenever new ids appeared since the last sweep
        if note_change() == last_count and not templates:
            break
        if not templates:
            continue
        grew = note_change()
        for tpl in templates:
            params = re.findall(r"\{(\w+)\}", tpl)
            if not params:
                continue
            pools = [sorted(known.get(p, set()))[:max_ids] for p in params]
            if not all(pools):
                continue
            for combo in itertools_product(*pools):
                concrete = tpl
                for p, val in zip(params, combo):
                    concrete = concrete.replace("{%s}" % p, str(val))
                if concrete.endswith(EXPORT_SUFFIX):
                    concrete = concrete + "?format=md"
                if concrete not in visited and len(visited) < max_req:
                    queue.append(concrete)
        if grew == last_count:
            break
        last_count = grew
    return {label: list(v.values()) for label, v in rows.items()}


def itertools_product(*pools):
    """Small local product to avoid importing itertools in the hot inner loop."""
    if not pools:
        yield ()
        return
    first, rest = pools[0], pools[1:]
    for head in first:
        for tail in itertools_product(*rest):
            yield (head,) + tail

